import {World,BLOCKS,HALF,HEIGHT,SEA,SIZE,raycast} from './world.js';
import {View,T} from './render.js';
import {TouchControls} from './touch-controls.js';
let touchControls=null;
const pressed=code=>keys.has(code)||!!touchControls?.keys.has(code);
const $=id=>document.getElementById(id), STORAGE='voxel-wilds-v1', SETTINGS='voxel-wilds-settings-v1';
document.body.classList.add('menu-open');
let world,view,mode='creative',selected=0,hotbar=[1,2,3,4,7,9,8,10,11],inventory={},tool=0;
let player=new T.Vector3(14.5,25,28.5),velocity=new T.Vector3(),yaw=-.18,pitch=-.12,grounded=false,flying=false,health=20,hunger=20,food=3;
let started=false,playing=false,locked=false,dragging=false,mouseDown=false,placeDown=false,modal=null,modalStack=[],time=480,day=1,lastTime=performance.now(),mineProgress=0,mineKey='',target=null,swing=0,walk=0,saveTimer=0,hungerTimer=0,stepTimer=0,lastPlace=0;
let sensitivity=.002,cycle=true,sound=true,audioCtx,saveDirty=false,loadedSave=null,warning='',suppressSave=false,saveWarned=false,lockWarned=false,contextLost=false,autoJump=matchMedia('(pointer:coarse)').matches;const keys=new Set();const coarsePointer=matchMedia('(pointer:coarse)');
const RECIPES=[{name:'橡木木板',out:7,n:4,cost:{4:1}},{name:'木制平台',out:17,n:1,cost:{7:4}},{name:'木镐',tool:1,cost:{7:5}},{name:'石镐',tool:2,cost:{8:3,7:2}},{name:'玻璃',out:9,n:4,cost:{6:4,12:1}},{name:'红砖',out:10,n:4,cost:{2:4,12:1}},{name:'萤石',out:11,n:2,cost:{14:1,6:2}}];
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function beep(type='place'){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);const t=audioCtx.currentTime;osc.type=type==='craft'?'sine':'triangle';osc.frequency.setValueAtTime(type==='mine'?145:type==='step'?85:type==='craft'?520:230,t);osc.frequency.exponentialRampToValueAtTime(type==='craft'?780:45,t+.12);gain.gain.setValueAtTime(type==='step'?.018:.055,t);gain.gain.exponentialRampToValueAtTime(.001,t+.16);osc.start(t);osc.stop(t+.17);}catch{}}
function validateSave(s){if(!s||s.version!==1||typeof s.seed!=='string'||s.seed.length>64||!Array.isArray(s.edits)||s.edits.length>SIZE*SIZE*HEIGHT)throw Error('这不是有效的原野存档');if(!Array.isArray(s.player)||s.player.length!==3||s.player.some((v,i)=>!Number.isFinite(v)||Math.abs(v)>(i===1?200:HALF)))throw Error('存档位置不正确');if(!['creative','survival'].includes(s.mode))throw Error('存档模式不正确');if(!Array.isArray(s.hotbar)||s.hotbar.length!==9||s.hotbar.some(b=>!BLOCKS[b]||[15,16].includes(b)))throw Error('快捷栏数据不正确');for(const[k,v]of Object.entries(s.inventory??{}))if(!BLOCKS[k]||!Number.isInteger(v)||v<0||v>100000)throw Error('背包数据不正确');return s;}
function saveObject(){return{version:1,seed:world.seed,edits:[...world.edits],player:player.toArray(),yaw,pitch,mode,hotbar,inventory,tool,health,hunger,food,time,day};}
function saveWorld(manual=false){try{localStorage.setItem(STORAGE,JSON.stringify(saveObject()));saveDirty=false;saveWarned=false;$('save-status').innerHTML='<i></i> 世界已保存';if(manual)toast('世界已保存在此浏览器');}catch{$('save-status').innerHTML='<i></i> 存储不可用';if(!saveWarned){saveWarned=true;toast('浏览器存储不可用或已写满，进度无法保存。请在世界设置中导出存档');}}}
function loadState(s){food=Number.isInteger(s.food)?Math.max(0,Math.min(999,s.food)):3;mode=s.mode;hotbar=[...s.hotbar];inventory={...s.inventory};tool=[0,1,2].includes(s.tool)?s.tool:0;health=Math.max(1,Math.min(20,s.health||20));hunger=Math.max(0,Math.min(20,s.hunger??20));time=Number.isFinite(s.time)?((s.time%1440)+1440)%1440:480;day=Math.max(1,s.day|0);player.fromArray(s.player);yaw=Number.isFinite(s.yaw)?s.yaw:-.18;pitch=Number.isFinite(s.pitch)?Math.max(-1.5,Math.min(1.5,s.pitch)):-.12;}
function updateMode(){document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));document.body.classList.toggle('survival-mode',mode==='survival');document.body.classList.toggle('can-fly',mode==='creative');const tf=$('touch-fly');if(tf){tf.classList.toggle('active',!!flying);tf.setAttribute('aria-pressed',flying?'true':'false');}$('mode-tag').textContent=mode==='creative'?(flying?'创造模式 · 飞行中':'创造模式 · 自由建造'):'生存模式 · 采集与合成';$('flight-hint').innerHTML=mode==='creative'?'<kbd>F</kbd> '+(flying?'退出飞行':'自由飞行'):'<kbd>Shift</kbd> 奔跑';$('health').textContent=mode==='survival'?'♥'.repeat(Math.ceil(health/2))+'♡'.repeat(10-Math.ceil(health/2)):'';$('hunger').textContent=mode==='survival'?'◆'.repeat(Math.ceil(hunger/2))+'◇'.repeat(10-Math.ceil(hunger/2)):'';renderHotbar();}
function renderHotbar(){$('hotbar').innerHTML=hotbar.map((id,i)=>`<button class="slot ${selected===i?'active':''}" data-slot="${i}" title="${BLOCKS[id].name} (${i+1})"><span class="num">${i+1}</span><img class="block-icon" src="${view.icon(id)}" alt="${BLOCKS[id].name}"><span class="count">${mode==='creative'?'∞':inventory[id]||0}</span></button>`).join('');$('selected-name').textContent=BLOCKS[hotbar[selected]].name;view.setHandBlock(hotbar[selected]);}
function renderInventory(){const creative=mode==='creative';$('inventory-mode').textContent=creative?'无限供应':'已采集资源';$('inventory-tip').textContent=creative?'点击任意方块，放入当前快捷栏位置。':'点击资源放入快捷栏。长按左键采集原木，开始你的第一次合成。';
 $('slot-picker').innerHTML=hotbar.map((id,i)=>`<button data-pick="${i}" class="${selected===i?'active':''}" title="快捷栏 ${i+1} · ${BLOCKS[id].name}" aria-label="快捷栏 ${i+1}"><img src="${view.icon(id)}" alt="">${i+1}</button>`).join('');
 $('block-grid').innerHTML=BLOCKS.map((b,id)=>!b||[15,16].includes(id)?'':`<button class="block-item ${!creative&&!inventory[id]?'unavailable':''}" data-block="${id}" title="${b.name}"><span class="block-count">${creative?'∞':inventory[id]||0}</span><img class="block-icon" alt="" src="${view.icon(id)}"><span class="block-title">${b.name}</span></button>`).join('');
 $('recipes').innerHTML=RECIPES.map((r,i)=>{const owned=!!r.tool&&tool>=r.tool;const enough=Object.entries(r.cost).every(([id,n])=>(inventory[id]||0)>=n);const can=!creative&&!owned&&enough;return `<div class="recipe"><div>${r.name} ${r.n?'×'+r.n:''}<small>${Object.entries(r.cost).map(([id,n])=>`${BLOCKS[id].name} ×${n}`).join(' + ')}</small></div><button data-craft="${i}" ${can?'':'disabled'}>${owned?'已制作':creative?'无需合成':'合成'}</button></div>`;}).join('');
 $('tool-status').innerHTML='当前工具：'+['徒手','木镐 · 挖矿加速','石镐 · 挖矿更快'][tool]+(creative?'<p class="muted">创造模式方块无限，直接从方块收藏取用即可。</p>':`<button id="eat-apple" class="secondary">苹果 ×${food} · 食用恢复饱食度 [R]</button><p class="muted">采集树叶有机会获得苹果。</p>`);
 const eatBtn=document.getElementById('eat-apple');if(eatBtn)eatBtn.onclick=eat;}
function eat(){if(food<=0){toast('苹果不足，试试采集树叶');return;}if(hunger>=20){toast('现在还不饿');return;}food--;hunger=Math.min(20,hunger+5);health=Math.min(20,health+2);saveDirty=true;beep('craft');updateMode();if(modal==='inventory')renderInventory();toast('吃下苹果 · 饱食度 +5，生命 +2');}
function loadSettings(){let s={};try{s=JSON.parse(localStorage.getItem(SETTINGS)||'{}')||{};}catch{}const f=Math.max(55,Math.min(100,Number.isFinite(+s.fov)?+s.fov:75));view.camera.fov=f;view.camera.updateProjectionMatrix();$('fov').value=f;$('fov-value').textContent=f+'°';const n=Math.max(10,Math.min(100,Number.isFinite(+s.sensitivity)?+s.sensitivity:50));sensitivity=n*.00004;$('sensitivity').value=n;$('sens-value').textContent=n+'%';if(typeof s.sound==='boolean')sound=s.sound;if(typeof s.cycle==='boolean')cycle=s.cycle;if(typeof s.autoJump==='boolean')autoJump=s.autoJump;$('sound').checked=sound;$('daycycle').checked=cycle;$('autojump').checked=autoJump;}
function saveSettings(){try{localStorage.setItem(SETTINGS,JSON.stringify({fov:+$('fov').value,sensitivity:+$('sensitivity').value,sound,cycle,autoJump}));}catch{}}
function craft(index){const r=RECIPES[index];if(!r)return;if(mode==='creative'){toast('创造模式方块无限，无需合成');return;}if(!Object.entries(r.cost).every(([id,n])=>(inventory[id]||0)>=n))return;for(const[id,n]of Object.entries(r.cost))inventory[id]-=n;if(r.tool)tool=Math.max(tool,r.tool);else inventory[r.out]=(inventory[r.out]||0)+r.n;saveDirty=true;beep('craft');toast('合成成功：'+r.name+(r.n?' ×'+r.n:''));renderInventory();renderHotbar();}
function release(){touchControls?.reset();keys.clear();mouseDown=false;placeDown=false;dragging=false;if(document.pointerLockElement)document.exitPointerLock();}
function openModal(id){if(modal===id)return;if(modal){$(modal).classList.add('hidden');modalStack.push(modal);}modal=id;playing=false;document.body.classList.remove('playing');$(id).classList.remove('hidden');document.body.classList.add('modal-open');release();if(id==='inventory')renderInventory();const panel=$(id).querySelector('.panel');if(panel)panel.focus();}
function closeModal(){const prev=modalStack.pop();if(modal)$(modal).classList.add('hidden');modal=null;if(prev){modal=prev;$(prev).classList.remove('hidden');if(prev==='inventory')renderInventory();const panel=$(prev).querySelector('.panel');if(panel)panel.focus();return;}document.body.classList.remove('modal-open');if(started){playing=true;document.body.classList.add('playing');lock();}}
function trapFocus(e){if(!modal)return;const box=$(modal);if(!box)return;const items=[...box.querySelectorAll('button:not([disabled]),input:not([disabled])')].filter(el=>el.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1],active=document.activeElement;if(!box.contains(active)){e.preventDefault();first.focus();return;}if(e.shiftKey&&active===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&active===last){e.preventDefault();first.focus();}}
async function lock(){if(matchMedia('(pointer:coarse)').matches)return;try{await $('world').requestPointerLock();}catch{warnLock();}}
function warnLock(){if(lockWarned)return;lockWarned=true;toast('当前环境无法锁定鼠标：拖动画面环顾，长按 Q 挖掘，按 G 放置');}
function enter(){started=true;playing=true;modal=null;modalStack=[];$('menu').classList.add('hidden');$('pause').classList.add('hidden');document.body.classList.remove('menu-open','modal-open');document.body.classList.add('playing');view.hand.visible=true;updateMode();lock();if(warning){toast(warning);warning='';}else toast(coarsePointer.matches?(mode==='creative'?'欢迎来到原野 · 拖动画面转视角，右侧可切换飞行':'长按「挖掘」采集原木，打开背包合成工具'):(mode==='creative'?'欢迎来到原野 · 按 F 自由飞行，按 E 打开背包':'收集原木，合成木板与木镐，开始你的第一天'));}
function collide(pos){const r=.29,h=1.72;for(let x=Math.floor(pos.x-r);x<=Math.floor(pos.x+r);x++)for(let z=Math.floor(pos.z-r);z<=Math.floor(pos.z+r);z++)for(let y=Math.floor(pos.y+.001);y<=Math.floor(pos.y+h);y++)if(world.solid(x,y,z))return true;return false;}
function safeSpawn(){player.set(14.5,world.surface(14,28)+1.02,28.5);velocity.set(0,0,0);flying=false;for(let i=0;collide(player)&&i<HEIGHT;i++)player.y++;}
function die(){safeSpawn();health=20;hunger=20;toast('你已在出生点重生，背包物品保留');updateMode();}
function damage(n){if(mode!=='survival')return;health=Math.max(0,health-n);if(health<=0)die();else toast('摔落受伤 −'+n);updateMode();}
function move(dt){const water=world.get(Math.floor(player.x),Math.floor(player.y+.5),Math.floor(player.z))===16;const headWater=water&&world.get(Math.floor(player.x),Math.floor(player.y+1.4),Math.floor(player.z))===16;const down=pressed('ShiftLeft')||pressed('ShiftRight');const speed=flying?(down?8:10):water?2.8:down?6.4:4.3;let f=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0)+(touchControls?.vector.y||0),r=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+(touchControls?.vector.x||0);const len=Math.max(1,Math.hypot(f,r));f/=len;r/=len;const dx=(r*Math.cos(yaw)-f*Math.sin(yaw))*speed*dt,dz=(-f*Math.cos(yaw)-r*Math.sin(yaw))*speed*dt;
 // 水中上浮：头还在水里时 4 m/s；头已出水时给 6.2 m/s 的“蹬边”速度。否则从 1 格深的水里只能浮到 12.83，永远够不到 13.0 的岸。
 if(flying)velocity.y=((pressed('Space')?1:0)-(down?1:0))*7;else{velocity.y-=water?7*dt:24*dt;if(water){velocity.y=Math.max(-2.5,velocity.y);if(pressed('Space'))velocity.y=Math.max(velocity.y,headWater?4:6.2);}else if(grounded&&pressed('Space')){velocity.y=8.3;grounded=false;beep('step');}}
 const dy=velocity.y*dt;grounded=false;let blocked=false;const steps=Math.max(1,Math.ceil(Math.max(Math.abs(dx),Math.abs(dy),Math.abs(dz))/.15));for(let i=0;i<steps;i++)for(const axis of['x','z','y']){const amount=({x:dx,z:dz,y:dy})[axis]/steps,old=player[axis];player[axis]+=amount;if(collide(player)){player[axis]=old;if(axis==='y'){if(velocity.y<0){grounded=true;if(velocity.y<-12)damage(Math.floor((-velocity.y-11)*1.2));}velocity.y=0;}else blocked=true;}}
 player.x=T.MathUtils.clamp(player.x,-HALF+1,HALF-1);player.z=T.MathUtils.clamp(player.z,-HALF+1,HALF-1);player.y=Math.min(HEIGHT+25,player.y);if(player.y<-8)safeSpawn();if(autoJump&&blocked&&grounded&&!water&&!flying&&(f||r)){velocity.y=8.3;grounded=false;beep('step');}if((f||r)&&grounded){walk+=dt*10;stepTimer+=dt;if(stepTimer>.42){beep('step');stepTimer=0;}}else walk*=Math.exp(-4.4*dt);
 if(mode==='survival'){hungerTimer+=dt;if(hungerTimer>25){hungerTimer=0;hunger=Math.max(0,hunger-(f||r?1:.25));if(hunger>15&&health<20)health=Math.min(20,health+1);if(hunger<=0&&health>0){health--;if(health<=0){die();return;}}updateMode();}}
 if(dx||dy||dz)saveDirty=true;
}
function mine(dt){if(!target||!(mouseDown||touchControls?.mining)){mineProgress=0;mineKey='';$('mine-meter').style.visibility='hidden';return;}const key=`${target.x},${target.y},${target.z}`;if(key!==mineKey){mineKey=key;mineProgress=0;}const b=BLOCKS[target.b];if(!Number.isFinite(b.time)){if(!mineProgress)toast('基岩无法破坏');mineProgress=1;return;}let duration=mode==='creative'?.15:b.time/(tool?[1,2,3.4][tool]:1);mineProgress+=dt/duration;swing+=dt*18;$('mine-meter').style.visibility='visible';$('mine-meter').firstElementChild.style.width=Math.min(100,mineProgress*100)+'%';if(mineProgress>=1){const {x,y,z,b:id}=target;world.set(x,y,z,0,true);view.changed(x,z);view.burst(x,y,z,id);if(mode==='survival'){const drop=b.drop||id;inventory[drop]=(inventory[drop]||0)+1;if(id===5&&Math.random()<.3){food++;toast('获得苹果 +1 · 按 R 食用');}}beep('mine');mineProgress=0;saveDirty=true;renderHotbar();}}
function place(){if(!target||performance.now()-lastPlace<180)return;lastPlace=performance.now();const{x,y,z,normal}=target,nx=x+normal.x,ny=y+normal.y,nz=z+normal.z,id=hotbar[selected];if(!world.inside(nx,ny,nz))return;if(mode==='survival'&&!(inventory[id]>0)){toast('没有足够的'+BLOCKS[id].name+'，按 E 查看背包');return;}const old=world.get(nx,ny,nz);if(old&&old!==16)return;world.set(nx,ny,nz,id);if(collide(player)){world.set(nx,ny,nz,old);toast('这里会挡住你，换个位置放置');return;}world.set(nx,ny,nz,id,true);if(mode==='survival')inventory[id]--;view.changed(nx,nz);beep();swing=2;saveDirty=true;renderHotbar();}
function miniMap(){const c=$('minimap').getContext('2d'),sz=144,step=3;c.clearRect(0,0,sz,sz);for(let py=0;py<sz;py+=step)for(let px=0;px<sz;px+=step){const x=Math.floor(player.x+(px-sz/2)*.38),z=Math.floor(player.z+(py-sz/2)*.38),h=world.surface(x,z),b=world.get(x,h,z);c.fillStyle=h<SEA?'#4b91a5':h>34?'#c2d1c1':b===6?'#b5ac7f':h>24?'#7f9362':'#658b4d';if(world.get(x,h+3,z)===4||world.get(x,h+4,z)===5)c.fillStyle='#365e3d';c.fillRect(px,py,step,step);}document.querySelector('.map-pointer').style.transform=`rotate(${-yaw}rad)`;}
function updateInfo(){$('coords').textContent=`X ${player.x.toFixed(0)}   Y ${player.y.toFixed(0)}   Z ${player.z.toFixed(0)}`;const h=world.surface(player.x,player.z);$('biome').textContent=h<=SEA+1?'河岸 · 浅水湿地':h>30?'高地 · 雪山之麓':'原野 · 温带森林';$('day-info').textContent=`${time>360&&time<1080?'☀':'☾'} 第 ${day} 天 · ${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.floor(time%60)).padStart(2,'0')}`;miniMap();}
let infoTimer=0;
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-lastTime)/1000,.04);lastTime=now;if(contextLost)return;try{
 if(playing){move(dt);if(cycle){time+=dt*1.7;if(time>=1440){time-=1440;day++;}}}
 if(!started){view.camera.position.set(14.5,world.surface(14,28)+6.2,28.5);view.camera.rotation.set(-.11,-.18+Math.sin(now*.000055)*.07,0);view.hand.visible=false;view.outline.visible=false;}
 else{view.camera.position.copy(player).add(new T.Vector3(0,1.57+(grounded?Math.sin(walk)*.025:0),0));view.camera.rotation.set(pitch,yaw,0);view.hand.visible=playing&&!coarsePointer.matches&&innerHeight>=480;const dir=new T.Vector3();view.camera.getWorldDirection(dir);target=raycast(world,view.camera.position,dir,mode==='creative'?8:5);view.outline.visible=!!target&&playing;if(target){view.outline.position.set(target.x+.5,target.y+.5,target.z+.5);$('target-name').textContent=BLOCKS[target.b].name;}else $('target-name').textContent='';if(playing){mine(dt);if((placeDown||touchControls?.placing)&&now-lastPlace>230)place();}view.hand.position.y=-.20+Math.sin(walk)*.013+Math.sin(swing)*.065;view.hand.rotation.x=-Math.sin(swing)*.2;if(!mouseDown&&!touchControls?.mining)swing*=.8;const underwater=world.get(Math.floor(player.x),Math.floor(player.y+1.57),Math.floor(player.z))===16;$('water-overlay').style.display=underwater?'block':'none';}
 view.animate(dt,time,started?player:view.camera.position,playing);infoTimer+=dt;saveTimer+=dt;if(infoTimer>.3){infoTimer=0;updateInfo();}if(saveTimer>15&&started){saveTimer=0;if(saveDirty)saveWorld();}
 }catch(err){console.error(err);playing=false;toast('运行遇到问题，请导出存档后刷新页面');}}
function bind(){
 $('play').onclick=enter;$('resume').onclick=closeModal;$('pause-btn').onclick=()=>{if(started)openModal('pause');};$('help-btn').onclick=$('controls-btn').onclick=()=>openModal('help');$('options-btn').onclick=$('pause-settings').onclick=()=>openModal('settings');$('pause-help').onclick=()=>openModal('help');$('save-btn').onclick=()=>saveWorld(true);
 $('exit-btn').onclick=()=>{saveWorld();started=false;playing=false;modal=null;modalStack=[];for(const id of['pause','settings','help','inventory'])$(id).classList.add('hidden');release();document.body.classList.remove('modal-open','playing');document.body.classList.add('menu-open');$('menu').classList.remove('hidden');$('play').innerHTML='继续探索 <span>↗</span>';};
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;flying=false;updateMode();saveDirty=true;});
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);
 $('hotbar').onclick=e=>{const b=e.target.closest('[data-slot]');if(b){selected=+b.dataset.slot;renderHotbar();}};
 $('slot-picker').onclick=e=>{const b=e.target.closest('[data-pick]');if(b){selected=+b.dataset.pick;renderHotbar();renderInventory();}};
 $('block-grid').onclick=e=>{const b=e.target.closest('[data-block]');if(b){hotbar[selected]=+b.dataset.block;renderHotbar();toast(BLOCKS[hotbar[selected]].name+' → 快捷栏 '+(selected+1));saveDirty=true;}};
 $('recipes').onclick=e=>{const b=e.target.closest('[data-craft]');if(b)craft(+b.dataset.craft);};
 $('fov').oninput=e=>{view.camera.fov=+e.target.value;view.camera.updateProjectionMatrix();$('fov-value').textContent=e.target.value+'°';saveSettings();};$('sensitivity').oninput=e=>{sensitivity=+e.target.value*.00004;$('sens-value').textContent=e.target.value+'%';saveSettings();};$('sound').onchange=e=>{sound=e.target.checked;saveSettings();};$('daycycle').onchange=e=>{cycle=e.target.checked;saveSettings();};$('autojump').onchange=e=>{autoJump=e.target.checked;saveSettings();};
 $('export-btn').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(saveObject())],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='voxel-wilds-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('存档已导出，可在其他设备导入');};
 $('import-btn').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>35e6)throw Error('存档文件过大');const s=validateSave(JSON.parse(await file.text()));const checkedWorld=new World(s.seed).generate();checkedWorld.applyEdits(s.edits);if(!confirm('导入会替换当前世界。确定已导出需要保留的存档？'))return;localStorage.setItem(STORAGE,JSON.stringify(s));suppressSave=true;started=false;location.reload();}catch(err){toast('导入失败：'+err.message);}e.target.value='';};
 $('new-world').onclick=()=>{if(!confirm('生成新世界会替换当前浏览器存档。继续吗？'))return;try{const seed=$('seed').value.trim()||'WILDS-'+Date.now();const w=new World(seed).generate();const fresh={version:1,seed,edits:[],player:[14.5,w.surface(14,28)+1.02,28.5],yaw:-.18,pitch:-.12,mode,hotbar:[1,2,3,4,7,9,8,10,11],inventory:{},tool:0,health:20,hunger:20,time:480,day:1};localStorage.setItem(STORAGE,JSON.stringify(fresh));suppressSave=true;started=false;location.reload();}catch{toast('浏览器存储不可用，请先允许本地存储');}};
 addEventListener('keydown',e=>{const t=e.target,inField=!!t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT');if(e.code==='Escape'){if(modal)closeModal();else if(started)openModal('pause');return;}if(e.code==='Tab'&&modal){trapFocus(e);return;}if(inField)return;if(['Space','KeyW','KeyA','KeyS','KeyD','KeyE','KeyF','KeyQ','KeyG','Digit1','Digit2','Digit3','Digit4','Digit5','Digit6','Digit7','Digit8','Digit9'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Tab'){if(modal)trapFocus(e);return;}if(e.code==='KeyE'&&started){if(modal==='inventory')closeModal();else if(!modal)openModal('inventory');return;}if(modal==='inventory'&&/^Digit[1-9]$/.test(e.code)){selected=+e.code.slice(5)-1;renderHotbar();renderInventory();return;}if(!playing)return;if(!locked&&e.code==='KeyQ'){mouseDown=true;return;}if(!locked&&e.code==='KeyG'){place();placeDown=true;return;}if(e.code==='KeyR'){eat();return;}keys.add(e.code);if(/^Digit[1-9]$/.test(e.code)){selected=+e.code.slice(5)-1;renderHotbar();}if(e.code==='KeyF'&&mode==='creative'){flying=!flying;velocity.y=0;updateMode();toast(flying?'自由飞行 · 空格上升，Shift 下降':'已退出飞行');}});
 addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyQ')mouseDown=false;if(e.code==='KeyG')placeDown=false;});addEventListener('blur',()=>{keys.clear();mouseDown=false;placeDown=false;if(playing)openModal('pause');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started){saveWorld();openModal('pause');}});
 document.addEventListener('pointerlockchange',()=>{const was=locked;locked=document.pointerLockElement===$('world');if(was&&!locked&&playing)openModal('pause');});
 document.addEventListener('pointerlockerror',warnLock);
 $('world').addEventListener('webglcontextlost',e=>{e.preventDefault();if(started){saveWorld();openModal('pause');}contextLost=true;$('loading').innerHTML='<div class="loading-cube">◇</div><strong>画面渲染已中断</strong><span>显卡上下文丢失。恢复后可继续；重新加载将读取最近存档。</span><button class="secondary" onclick="location.reload()">重新加载</button>';$('loading').classList.remove('hidden');});
 $('world').addEventListener('webglcontextrestored',()=>{contextLost=false;$('loading').classList.add('hidden');});
 $('world').addEventListener('contextmenu',e=>e.preventDefault());$('world').addEventListener('pointerdown',e=>{if(!playing)return;if(e.pointerType==='touch')return;if(!locked){lock();dragging=true;}if(e.button===0&&!dragging)mouseDown=true;if(e.button===2&&!dragging){place();placeDown=true;}});addEventListener('pointerup',()=>{mouseDown=false;placeDown=false;dragging=false;});addEventListener('pointercancel',()=>{mouseDown=false;placeDown=false;dragging=false;keys.clear();});
 addEventListener('mousemove',e=>{if(!playing||(!locked&&!dragging))return;yaw-=e.movementX*sensitivity;pitch=T.MathUtils.clamp(pitch-e.movementY*sensitivity,-1.54,1.54);});$('world').addEventListener('wheel',e=>{if(!playing)return;e.preventDefault();selected=(selected+(e.deltaY>0?1:8))%9;renderHotbar();},{passive:false});
 touchControls=new TouchControls({stick:$('joystick'),knob:$('joystick-knob'),canvas:$('world'),buttons:document.querySelectorAll('#mobile-controls [data-key],#touch-mine,#touch-place'),isPlaying:()=>playing,onLook:(dx,dy)=>{yaw-=dx*.005;pitch=T.MathUtils.clamp(pitch-dy*.005,-1.54,1.54);},onPlace:place});$('touch-bag').onclick=()=>openModal('inventory');
 $('touch-fly').onclick=()=>{if(mode!=='creative'){toast('生存模式无法飞行');return;}flying=!flying;velocity.y=0;updateMode();toast(flying?'自由飞行 · 跳跃键上升，下降键降低':'已退出飞行');};
 addEventListener('beforeunload',()=>{if(started&&!suppressSave)saveWorld();});
}
async function init(){try{try{const raw=localStorage.getItem(STORAGE);if(raw)loadedSave=validateSave(JSON.parse(raw));}catch{warning='旧存档无法读取，当前使用新世界；可通过设置导出存档。';}
 world=new World(loadedSave?.seed||'WILDS-2026').generate();if(loadedSave){try{world.applyEdits(loadedSave.edits);loadState(loadedSave);}catch{loadedSave=null;world=new World('WILDS-2026').generate();safeSpawn();warning='存档数据异常，已进入新世界';}}else safeSpawn();
 view=new View($('world'),world);await new Promise(r=>setTimeout(r,50));view.buildAll();if(collide(player))safeSpawn();$('seed').value=world.seed;loadSettings();renderHotbar();updateMode();bind();if(loadedSave){$('play').innerHTML='继续探索 <span>↗</span>';$('world-badge-text').textContent='已找到存档 · '+world.edits.size+' 处建造痕迹';}$('loading').classList.add('hidden');lastTime=performance.now();requestAnimationFrame(frame);
 window.__voxel={get state(){return{ready:true,playing,mode,player:player.toArray(),grounded,flying,health,hunger,selected,hotbar:[...hotbar],inventory:{...inventory},edits:world.edits.size,target,tool,day,time,renderCalls:view.renderer.info.render.calls,triangles:view.renderer.info.render.triangles};},world,view};
 }catch(err){console.error(err);$('loading').innerHTML='<strong>原野暂时无法加载</strong><span>请使用支持 WebGL 的新版 Chrome 或 Edge，并开启硬件加速。</span><button class="secondary" onclick="location.reload()">重新加载</button>';}}
init();
